# setting here is a configuration error -- it must reference a concrete
# implementation module.
INTERFACE_MODULE = "prefect.server.worker_communication.cleanup_queue"


class WorkerCleanupQueue(abc.ABC):
    """
    Interface for a reliable, lease-based cleanup queue used to deliver
    cleanup messages to workers over the worker channel.

    Implementations provide idempotent enqueue, one-active-reservation-per
    -work-pool leasing, acknowledgement, release with dead-lettering,
    lease renewal and expiry, and wakeup notification.
    """

    @abc.abstractmethod
    def clear(self) -> None:
        """Reset all internal queue state."""

    @abc.abstractmethod
    def enqueue(
        self,
        message_id: UUID,
        idempotency_key: str,
        work_pool_id: UUID,
        kind: Any,
        target: dict[str, Any],
        data: Optional[dict[str, Any]] = None,
        work_queue_id: Optional[UUID] = None,
    ) -> Any:
        """Enqueue a cleanup message (idempotent by idempotency_key + pool)."""

    @abc.abstractmethod
    def reserve(
        self,
        work_pool_id: UUID,
        preferred_work_queue_ids: Optional[list[UUID]] = None,
        cleanup_kinds: Optional[list[Any]] = None,
    ) -> Any:
        """Reserve the next available message for a work pool."""

    @abc.abstractmethod
    def ack(
        self, work_pool_id: UUID, message_id: UUID, reservation_token: str
    ) -> Any:
        """Acknowledge successful processing of a reserved message."""

    @abc.abstractmethod
    def release(
        self,
        work_pool_id: UUID,
        message_id: UUID,
        reservation_token: str,
        reason: str,
    ) -> Any:
        """Release a reserved message for redelivery, or dead-letter it."""

    @abc.abstractmethod
    def renew(
        self, work_pool_id: UUID, message_id: UUID, reservation_token: str
    ) -> Any:
        """Extend the lease of an active reservation."""

    @abc.abstractmethod
    def read_message(self, work_pool_id: UUID, message_id: UUID) -> Any:
        """Read a stored message scoped to a work pool."""

    @abc.abstractmethod
    def read_dead_letter(self, work_pool_id: UUID, message_id: UUID) -> Any:
        """Read a dead-letter entry scoped to a work pool."""

    @abc.abstractmethod
    def read_wakeup_sequence(self, work_pool_id: UUID) -> int:
        """Return the current wakeup sequence for a work pool."""

    @abc.abstractmethod
    async def wait_for_wakeup(
        self,
        work_pool_id: UUID,
        after: Optional[int] = None,
        timeout: Optional[float] = None,
    ) -> Any:
        """Block until the wakeup sequence advances past ``after``."""

    @abc.abstractmethod
    def expire_leases(
        self, work_pool_id: Optional[UUID] = None, limit: Optional[int] = None
    ) -> Any:
        """Expire overdue leases, redelivering or dead-lettering them."""


def get_worker_cleanup_queue() -> WorkerCleanupQueue:
    """
    Load and return a ``WorkerCleanupQueue`` instance from the module configured
    via ``PREFECT_SERVER_WORKER_CHANNEL_CLEANUP_QUEUE_STORAGE``.

    Raises:
        ValueError: if the configured module is the interface package itself
            rather than a concrete implementation module.
    """
    storage = get_current_settings().server.worker_channel.cleanup_queue_storage

    if storage == INTERFACE_MODULE:
        raise ValueError(
            "PREFECT_SERVER_WORKER_CHANNEL_CLEANUP_QUEUE_STORAGE must point to a "
            "concrete WorkerCleanupQueue implementation module (for example "
            f"'{INTERFACE_MODULE}.memory'), not the interface package "
            f"'{INTERFACE_MODULE}' itself."
        )

    module = importlib.import_module(storage)
    return module.WorkerCleanupQueue()


